  `id` int NOT NULL,
  `user_id` int NOT NULL,
  `type` enum('charge','purchase','refund') NOT NULL,
  `amount` int NOT NULL,
  `balance_after` int NOT NULL,
  `description` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Table structure for table `works`
--

CREATE TABLE `works` (
  `id` int NOT NULL,
  `title_fa` varchar(255) NOT NULL,
  `title_en` varchar(255) NOT NULL,
  `information` text,
  `release_year` int DEFAULT NULL,
  `publication_status_id` int DEFAULT NULL,
  `age_rating` varchar(10) DEFAULT NULL,
  `rating` decimal(2,1) DEFAULT '0.0',
  `content_status` enum('free','subscription','purchase') DEFAULT 'free',
  `price` int DEFAULT '0',
  `duration_per_episode` int DEFAULT NULL,
  `poster_image_url` varchar(500) DEFAULT NULL,
  `summary` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

